from collections import OrderedDict
from typing import Any, Dict, List, Optional


def simulate_ttl_lru(capacity: int, events: List[Dict[str, Any]]) -> List[Any]:
    if capacity < 0:
        raise ValueError("capacity must be non-negative")

    # key -> (value, expires_at)
    cache: "OrderedDict[str, Any]" = OrderedDict()
    results: List[Any] = []

    def evict_expired(current_time: int) -> None:
        # Remove all entries with expires_at <= current_time
        while cache:
            k = next(iter(cache))
            _, expires_at = cache[k]
            if expires_at <= current_time:
                cache.popitem(last=False)
            else:
                break

    for ev in events:
        op = ev.get("op")
        t = ev.get("time")

        # Ensure time is an int as expected by problem statement
        if not isinstance(t, int):
            raise TypeError("event time must be an int")

        evict_expired(t)

        if op == "put":
            if capacity == 0:
                continue

            key = ev["key"]
            value = ev["value"]
            ttl = ev["ttl"]
            if not isinstance(ttl, int):
                raise TypeError("ttl must be an int")
            if ttl <= 0:
                raise ValueError("ttl must be a positive integer")

            expires_at = t + ttl

            if key in cache:
                # Overwrite value and expire time, mark as recently used.
                cache.pop(key, None)
            cache[key] = (value, expires_at)
            cache.move_to_end(key, last=True)

            # LRU eviction to keep size <= capacity
            while len(cache) > capacity:
                cache.popitem(last=False)

        elif op == "get":
            key = ev["key"]
            if key not in cache:
                results.append(None)
                continue

            value, expires_at = cache[key]
            # TTL eviction is already done before each event, but keep safety.
            if expires_at <= t:
                cache.pop(key, None)
                results.append(None)
                continue

            # Hit: update as recently used.
            cache.move_to_end(key, last=True)
            results.append(value)

        else:
            raise ValueError(f"unknown op: {op}")

    return results

